uniform float amzp_depth;
uniform float amzp_profile;
uniform float amzp_lightAngle;
uniform float amzp_lightHeight;
uniform float amzp_shade;
layout(color) uniform half4 amzp_shadowCol;
uniform float amzp_gloss;
uniform float amzp_shininess;
uniform float amzp_coat;
uniform float amzp_reflAmt;
layout(color) uniform half4 amzp_hiCol;
uniform float amzp_matMode;
layout(color) uniform half4 amzp_tintCol;
uniform float amzp_mixAmt;
uniform float amzp_quality;
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float tapsQ() { float q = floor(clamp(amzp_quality, 1.0, 4.0) + 0.5); return q < 1.5 ? 8.0 : (q < 2.5 ? 12.0 : (q < 3.5 ? 18.0 : 24.0)); }
    float blurA(int t, float2 dir, bool src) {
        float2 uv = amzScreenNorm();
        float r = amzp_bevelSize * pxs();
        float N = tapsQ();
        float2 st = dir / screen.zw * r / N;
        float s = 0.0, ws = 0.0;
        for (int i = -24; i <= 24; i++) {
            float fi = float(i);
            if (abs(fi) > N) continue;
            float x = fi / N;
            float w = exp(-4.0 * x * x);
            float4 c = amzTexture(t, uv + st * fi);
            s += (src ? c.a : c.r) * w; ws += w;
        }
        return s / max(ws, 1e-5);
    }
    float prof(float x) {
        x = clamp(x, 0.0, 1.0);
        if (int(amzp_profile) == 0) return x * x * (3.0 - 2.0 * x);
        if (int(amzp_profile) == 1) return sqrt(max(1.0 - (1.0 - x) * (1.0 - x), 0.0));
        if (int(amzp_profile) == 2) return x;
        return sqrt(x);
    }
    float H(float2 q) {
        float b = amzTexture(2, q).r;
        float x = int(amzp_profile) == 3 ? clamp((b - 0.5) * 2.0, 0.0, 1.0) : clamp((b - 0.5) * 2.4, 0.0, 1.0);
        return prof(x);
    }
    float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
