        float4 orig = amzTexture(0, uv);
        if (orig.a < 0.0005) { amzOutput = orig; return; }
        float3 oc = orig.rgb / orig.a;
        float2 p1 = 1.5 / screen.zw;
        float r = amzp_bevelSize * pxs();
        float hx = H(uv + float2(p1.x, 0.0)) - H(uv - float2(p1.x, 0.0));
        float hy = H(uv + float2(0.0, p1.y)) - H(uv - float2(0.0, p1.y));
        float k = amzp_depth * r / 3.0;
        float3 N = normalize(float3(-hx * k, -hy * k, 1.0));
        float la = radians(amzp_lightAngle), le = radians(amzp_lightHeight);
        float3 L = normalize(float3(cos(la) * cos(le), sin(la) * cos(le), sin(le)));
