        float flat0 = L.z;
        float sh = (nl - flat0) * amzp_shade * 1.6;
        float3 base = oc;
        if (int(amzp_matMode) == 1) base = amzp_tintCol.rgb * (0.35 + 0.65 * luma(oc) * 1.2);
        float3 col;
        if (sh >= 0.0) col = base * (1.0 + sh * 0.6) + sh * 0.12;
        else col = mix(base, amzp_shadowCol.rgb * base * 0.6 + amzp_shadowCol.rgb * 0.15, clamp(-sh, 0.0, 1.0));
