        float nh = max(dot(N, Hv), 0.0);
        float spec = pow(nh, amzp_shininess) * amzp_gloss * 1.2;
        float hot = pow(nh, amzp_shininess * 6.0 + 20.0) * amzp_coat * 1.8;
        float3 R = reflect(-V, N);
        float fres = pow(1.0 - clamp(N.z, 0.0, 1.0), 2.0);
        float box = smoothstep(0.55, 0.9, dot(normalize(R.xy + 1e-5), L.xy / max(length(L.xy), 1e-4)) * 0.5 + 0.5) * smoothstep(0.02, 0.35, length(R.xy));
