        if (int(amzp_matMode) == 2) {
            float ml = luma(oc);
            float3 mt = mix(float3(ml), oc, 0.6);
            float envM = 0.25 + 0.75 * smoothstep(-0.3, 0.8, dot(R.xy, L.xy) + R.z * 0.3);
            col = mt * (0.25 + envM * 0.9) * (1.0 + sh * 0.5);
            env *= 1.5;
        }
        col += amzp_hiCol.rgb * (spec + hot + env);
        col = clamp(col, 0.0, 1.0);
        float4 res = float4(col * orig.a, orig.a);
        amzOutput = mix(orig, res, clamp(amzp_mixAmt, 0.0, 1.0));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

